import assert from 'node:assert/strict';
import { LineReader, readLines } from './src/streaming-utf8/lines.mjs';
import { createRepository } from './src/cursor-pagination/repository.mjs';
import { collectAll } from './src/cursor-pagination/collect.mjs';
import { resolveName } from './src/dependency-aliases/registry.mjs';
import { buildOrder } from './src/dependency-aliases/order.mjs';
import { mergeLayers } from './src/layered-config/merge.mjs';

const enc = new TextEncoder();
const bytes = enc.encode('€\r\n\nend\r');
assert.deepEqual(await readLines([bytes.subarray(0, 1), bytes.subarray(1, 3), bytes.subarray(3)]), ['€', '', 'end\r']);
const r = new LineReader();
assert.deepEqual(r.feed(enc.encode('a\n')), ['a']);
assert.deepEqual(r.end(), []);
assert.deepEqual(await readLines([[0x61, 0xe2].length ? new Uint8Array([0x61, 0xe2]) : new Uint8Array()]), ['a�']);

const repo = createRepository([{id:1, deleted:true}, {id:2, deleted:true}, {id:3}, {id:4, deleted:true}, {id:5}]);
assert.deepEqual(await collectAll(repo, {limit:2}), [{id:3}, {id:5}]);
const repeated = { async page({cursor}) { return {items:[], nextCursor:cursor === null ? 1 : 1}; } };
await assert.rejects(collectAll(repeated), /Repeated cursor/);

const nodes = { real: {}, dep: {dependencies:['r']}, app:{dependencies:['dep']} };
const aliases = {r:'real', appAlias:'app', depAlias:'dep'};
assert.equal(resolveName('r', nodes, aliases), 'real');
assert.deepEqual(buildOrder({nodes, aliases}, ['appAlias','real']), ['real','dep','app']);
assert.throws(() => resolveName('a', {}, {a:'b',b:'a'}), /cycle/i);
assert.throws(() => buildOrder({nodes:{a:{dependencies:['alias']},b:{dependencies:['a']}}, aliases:{alias:'b'}}, ['a']), /cycle/i);

const base={endpoint:'x',retries:4, nested:{a:1, untouched:{v:2}}, arr:[{x:1}]};
const out=mergeLayers(base, {endpoint:'', retries:0, nested:{a:false}, arr:[{x:2}], nullish:null, omitted:undefined});
assert.deepEqual(out, {endpoint:'',retries:0,nested:{a:false,untouched:{v:2}},arr:[{x:2}],nullish:null});
assert.notEqual(out.nested, base.nested);
assert.notEqual(out.nested.untouched, base.nested.untouched);
assert.notEqual(out.arr, base.arr);
assert.notEqual(out.arr[0], base.arr[0]);
out.nested.untouched.v = 9; out.arr[0].x = 9;
assert.equal(base.nested.untouched.v, 2); assert.equal(base.arr[0].x, 1);
console.log('additional contract checks passed');
EOF

