export function resolveName(name, nodes, aliases) {
  const target = aliases[name] ?? name;
  if (!(target in nodes)) throw new Error('Unknown node: ' + target);
  return target;
}

patches.after:
export function resolveName(name, nodes, aliases = {}) {
  const seen = new Set();
  let target = name;

  while (Object.hasOwn(aliases, target)) {
    if (seen.has(target)) throw new Error('Alias cycle: ' + target);
    seen.add(target);
    target = aliases[target];
  }

  if (!Object.hasOwn(nodes, target)) throw new Error('Unknown node: ' + target);
  return target;
}

